/* Mode: Run Once for All Items. */
const books = $input.all().map(item => item.json);

const clean = value =>
  String(value ?? "").replace(/\s+/g, " ").trim();

const normalize = value =>
  clean(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[’‘]/g, "'")
    .toLowerCase();

const missingLabels = new Set([
  "",
  "non renseigne",
  "inconnu",
  "inconnue",
  "null",
  "undefined",
  "n/a",
  "sans genre",
  "sans auteur",
  "auteur inconnu",
  "sans editeur"
]);

function toNumber(value) {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : 0;
  }

  let text = clean(value).replace(/[\s\u00a0\u202f€]/g, "");

  if (!text) return 0;

  if (text.includes(",") && text.includes(".")) {
    text = text.lastIndexOf(",") > text.lastIndexOf(".")
      ? text.replace(/\./g, "").replace(",", ".")
      : text.replace(/,/g, "");
  } else {
    text = text.replace(",", ".");
  }

  const parsed = Number(text);
  return Number.isFinite(parsed) ? parsed : 0;
}

function toYear(value) {
  const match = clean(value).match(/\b([12]\d{3})\b/);
  return match ? Number(match[1]) : null;
}

function getLabels(value, fallback) {
  let values = value;

  if (
    typeof values === "string" &&
    values.trim().startsWith("[")
  ) {
    try {
      values = JSON.parse(values);
    } catch {}
  }

  if (!Array.isArray(values)) {
    values = [values];
  }

  const unique = new Map();

  for (const item of values) {
    const label = clean(
      item && typeof item === "object"
        ? item.name || item.labelFr || ""
        : item
    );

    const key = normalize(label);

    if (!missingLabels.has(key)) {
      unique.set(key, label);
    }
  }

  return unique.size ? [...unique.values()] : [fallback];
}

function addLabels(counter, labels) {
  for (const label of labels) {
    const key = normalize(label);
    const entry = counter.get(key) || { label, count: 0 };

    entry.count++;
    counter.set(key, entry);
  }
}

function sortCounts(counter) {
  return Object.fromEntries(
    [...counter.values()]
      .sort((a, b) =>
        b.count - a.count ||
        a.label.localeCompare(b.label, "fr")
      )
      .map(entry => [entry.label, entry.count])
  );
}

function createGroup() {
  return {
    total: 0,
    genres: new Map(),
    authors: new Map(),
    publishers: new Map(),
    decades: new Map(),
    withoutYear: 0
  };
}

function addBook(group, book, releaseYear) {
  group.total++;

  addLabels(
    group.genres,
    getLabels(book.genre, "Sans genre")
  );

  addLabels(
    group.authors,
    getLabels(book.auteur, "Auteur inconnu")
  );

  addLabels(
    group.publishers,
    getLabels(book.editeur, "Sans éditeur")
  );

  if (releaseYear === null) {
    group.withoutYear++;
  } else {
    const decade = Math.floor(releaseYear / 10) * 10;

    group.decades.set(
      decade,
      (group.decades.get(decade) || 0) + 1
    );
  }
}

function exportGroup(group) {
  const decades = Object.fromEntries(
    [...group.decades.entries()]
      .sort((a, b) => b[0] - a[0])
      .map(([decade, count]) => [decade + "s", count])
  );

  if (group.withoutYear > 0) {
    decades["Sans année"] = group.withoutYear;
  }

  return {
    Total: group.total,
    Genre: sortCounts(group.genres),
    Auteurs: sortCounts(group.authors),
    "Éditeurs": sortCounts(group.publishers),
    "Décennies": decades
  };
}

function createRange() {
  return {
    min: Infinity,
    max: -1,
    minTitle: "Aucun",
    maxTitle: "Aucun"
  };
}

function updateRange(range, pages, title) {
  if (pages < range.min) {
    range.min = pages;
    range.minTitle = title;
  }

  if (pages > range.max) {
    range.max = pages;
    range.maxTitle = title;
  }
}

function rangeText(range, side) {
  const pages =
    Number.isFinite(range[side]) && range[side] >= 0
      ? range[side]
      : 0;

  return range[side + "Title"] + " (" + pages + " p.)";
}

const ownedGroup = createGroup();
const wishGroup = createGroup();

const globalReadRange = createRange();
const ownedReadRange = createRange();

let ownedRead = 0;
let ownedUnread = 0;
let ownedReading = 0;
let unownedRead = 0;
let unclassified = 0;

let pagesRead = 0;
let collectionCents = 0;
let withoutYear = 0;

/* Keep separate editions even when they share the same id_unique. */
for (const book of books) {
  const status = normalize(book.statut);
  const title = clean(book.titre) || "Titre inconnu";

  const pages = Math.max(
    0,
    Math.trunc(toNumber(book.nb_pages))
  );

  const releaseYear = toYear(book.annee_sortie);

  /* Anchored ownership prevents "Non possédé" from matching. */
  const isOwned = /^possede(?:\s|$)/.test(status);

  /* Exact reading states exclude unread and in-progress books. */
  const isRead = [
    "possede et lu",
    "non possede mais lu",
    "non possede et lu"
  ].includes(status);

  const isReading = status === "possede et je lis";

  const isWish = [
    "liste de souhait",
    "liste de souhaits"
  ].includes(status);

  if (releaseYear === null) {
    withoutYear++;
  }

  if (isOwned) {
    addBook(ownedGroup, book, releaseYear);

    collectionCents += Math.round(
      Math.max(0, toNumber(book.Prix)) * 100
    );

    if (isRead) {
      ownedRead++;
    } else if (isReading) {
      ownedReading++;
    } else {
      ownedUnread++;
    }
  }

  if (isWish) {
    addBook(wishGroup, book, releaseYear);
  }

  if (isRead) {
    if (!isOwned) {
      unownedRead++;
    }

    pagesRead += pages;

    updateRange(globalReadRange, pages, title);

    if (isOwned) {
      updateRange(ownedReadRange, pages, title);
    }
  }

  if (!isOwned && !isWish && !isRead) {
    unclassified++;
  }
}

const totalRead = ownedRead + unownedRead;

const possession = exportGroup(ownedGroup);
const souhaits = exportGroup(wishGroup);

const donneesDominantes = {
  "En possession": possession,
  "Liste de souhait": souhaits
};

return [
  {
    json: {
      Pages: pagesRead,
      Prix: (collectionCents / 100).toFixed(2).replace(".", ","),

      "En possession (Total)": ownedGroup.total,
      "En possession et Lu": ownedRead,
      "En possession et Non lu": ownedUnread,
      "En possession et Je lis": ownedReading,
      "Non possédé et Lu": unownedRead,
      "Liste de souhait": wishGroup.total,
      "Non classé": unclassified,

      Livres_Total: books.length,
      Livres_Bibliotheque: ownedGroup.total,
      Livres_Lus_Total: totalRead,

      Moyenne_Pages:
        totalRead > 0
          ? Math.round(pagesRead / totalRead)
          : 0,

      Genre: "Roman",

      Global_Max: rangeText(globalReadRange, "max"),
      Global_Min: rangeText(globalReadRange, "min"),
      Bibli_Max: rangeText(ownedReadRange, "max"),
      Bibli_Min: rangeText(ownedReadRange, "min"),

      withoutYear,

      /* Preserve existing mappings with rankings restricted to owned books. */
      Genres: possession.Genre,
      Auteurs: possession.Auteurs,
      Editeurs: possession["Éditeurs"],
      Decennies: possession["Décennies"],

      donneesDominantes
    }
  }
];

