// Match the type of the annee_sortie column in your Data Table.
const YEAR_AS_NUMBER = false;

const clean = value =>
  String(value ?? "").replace(/\s+/g, " ").trim();

function number(value) {
  const text = clean(value)
    .replace(/[\s\u00a0\u202f]/g, "")
    .replace(",", ".");

  const match = text.match(/^\d+(?:\.\d+)?/);
  return match ? Number(match[0]) : 0;
}

function year(value) {
  const match = clean(value).match(/\b([12]\d{3})\b/);
  return match ? Number(match[1]) : null;
}

function makeIdUnique(title, author, url) {
  const base = String((title || "") + (author || ""))
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9]/g, "")
    .toLowerCase();

  return base || String(url || "")
    .replace(/[^a-zA-Z0-9]/g, "")
    .toLowerCase();
}

function unwrap(value) {
  if (typeof value === "string") {
    return unwrap(JSON.parse(value));
  }

  if (Array.isArray(value)) {
    return value.flatMap(unwrap);
  }

  if (!value || typeof value !== "object") {
    return [];
  }

  if (value.error) {
    throw new Error(
      "Gleeph extraction failed: " + String(value.error)
    );
  }

  if (
    value.statut_session &&
    value.statut_session !== "valide"
  ) {
    throw new Error("Invalid Gleeph session.");
  }

  if ("data" in value) return unwrap(value.data);
  if ("body" in value) return unwrap(value.body);
  if ("titre" in value) return [value];

  throw new Error("Unexpected Gleeph response.");
}

const output = [];

for (const [index, item] of $input.all().entries()) {
  for (const book of unwrap(item.json)) {
    const title = clean(book.titre) || "Titre inconnu";
    const author = clean(book.auteur) || "Auteur inconnu";
    const releaseYear = year(book.annee_sortie);

    const genres = Array.isArray(book.genre)
      ? JSON.stringify(
          [...new Set(book.genre.map(clean).filter(Boolean))]
        )
      : clean(book.genre);

    output.push({
      json: {
        id_unique:
          clean(book.id_unique) ||
          makeIdUnique(title, author, book.url),

        titre: title,
        auteur: author,
        genre: genres || "Non renseigné",
        statut: clean(book.statut) || "Non classé",

        nb_pages: String(Math.trunc(number(book.nb_pages))),
        Prix: number(book.Prix).toFixed(2),

        editeur: clean(book.editeur),

        annee_sortie: YEAR_AS_NUMBER
          ? releaseYear
          : releaseYear === null
            ? ""
            : String(releaseYear)
      },

      pairedItem: { item: index }
    });
  }
}

return output;

